import test from 'node:test';
import assert from 'node:assert/strict';
import {exportRows} from '../src/export.js';
const rows=[{id:'a',tenantId:'t1',name:'Ada'},{id:'b',tenantId:'t2',name:'Grace'},{id:'c',tenantId:'t1',name:'Lin'}];
test('same tenant filtered result',()=>assert.deepEqual(exportRows(rows,'t1',['a','b']).map(x=>x.id),['a']));
test('empty choice stays empty',()=>assert.deepEqual(exportRows(rows,'t1',[]),[]));
test('input stays unchanged',()=>{const before=JSON.stringify(rows);exportRows(rows,'t1',['a']);assert.equal(JSON.stringify(rows),before);});
